import json, sys, re

py = json.load(open(sys.argv[1]))
js = json.load(open(sys.argv[2]))
cases = [json.loads(l) for l in open(sys.argv[3]) if l.strip()]

assert len(py) == len(js) == len(cases), (len(py), len(js), len(cases))

def merge(cps):
    # JS strings are UTF-16: adjacent [high, low] surrogates are indistinguishable
    # from the astral codepoint they encode. Compare under the JS view.
    out, i = [], 0
    while i < len(cps):
        c = cps[i]
        if 0xD800 <= c <= 0xDBFF and i + 1 < len(cps) and 0xDC00 <= cps[i+1] <= 0xDFFF:
            out.append(0x10000 + (c - 0xD800) * 0x400 + (cps[i+1] - 0xDC00))
            i += 2
        else:
            out.append(c)
            i += 1
    return out

def norm(r):
    if not r["ok"]:
        # strip the exception class name; compare the message only
        return ("err", re.sub(r"^[A-Za-z]+: ", "", r["err"], count=1))
    return ("ok", r.get("s"), tuple(merge(r["cps"])) if "cps" in r else None)

bad = 0
for i, (p, j, c) in enumerate(zip(py, js, cases)):
    if norm(p) != norm(j):
        bad += 1
        if bad <= 25:
            print("MISMATCH case", i, json.dumps(c)[:160])
            print("   py:", json.dumps(p)[:200])
            print("   js:", json.dumps(j)[:200])
print("total=%d mismatches=%d" % (len(cases), bad))
sys.exit(1 if bad else 0)

