import { readFileSync } from 'node:fs';
const pyRanges = JSON.parse(readFileSync('/tmp/wf/_pybidi.json','utf8'));
// expand to a lookup
const bidiOf = (cp) => {
  let lo=0, hi=pyRanges.length-1;
  while (lo<=hi){ const m=(lo+hi)>>1; const r=pyRanges[m];
    if (cp<r[0]) hi=m-1; else if (cp>r[1]) lo=m+1; else return r[2]; }
  return 'UNASSIGNED';
};
const AL = ['Arabic','Syriac','Thaana','Manichaean','Sogdian','Hanifi_Rohingya','Chorasmian','Old_Uyghur'];
const R = ['Hebrew','Nko','Samaritan','Mandaic','Adlam','Cypriot','Phoenician','Lydian','Kharoshthi',
  'Imperial_Aramaic','Avestan','Inscriptional_Parthian','Inscriptional_Pahlavi','Psalter_Pahlavi',
  'Old_Turkic','Old_Hungarian','Hatran','Elymaic','Nabataean','Palmyrene','Mende_Kikakui',
  'Old_North_Arabian','Old_South_Arabian','Old_Sogdian','Yezidi','Meroitic_Cursive',
  'Meroitic_Hieroglyphs','Cypro_Minoan'];

function report(list, expect){
  for (const sc of list){
    let re;
    try { re = new RegExp(`\\p{Script=${sc}}`,'u'); } catch(e){ console.log(`!! ${sc}: NOT A VALID SCRIPT NAME IN NODE`); continue; }
    // only consider LETTERS (the rule says "Letters: use Script to pick R vs AL vs L")
    const letter = new RegExp(`\\p{L}`,'u');
    const hist = {};
    let n=0;
    for (let cp=0; cp<=0x10FFFF; cp++){
      if (cp>=0xD800 && cp<=0xDFFF) continue;
      const s = String.fromCodePoint(cp);
      if (!re.test(s)) continue;
      if (!letter.test(s)) continue;
      n++;
      const b = bidiOf(cp);
      hist[b] = (hist[b]||0)+1;
    }
    const keys = Object.keys(hist).sort((a,b)=>hist[b]-hist[a]);
    const ok = keys.length===1 && keys[0]===expect;
    console.log(`${ok?'OK  ':'DIFF'} ${sc.padEnd(24)} letters=${String(n).padStart(4)} ${keys.map(k=>`${k}:${hist[k]}`).join(' ')}`);
  }
}
console.log('=== candidate AL scripts (expect all letters bidi=AL) ===');
report(AL,'AL');
console.log('=== candidate R scripts (expect all letters bidi=R) ===');
report(R,'R');
EOF
