// Canonical ordering (NFD) reorders a pair of combining marks a,b iff ccc(a) > ccc(b) > 0.
const swaps = (a,b) => {
  const s = String.fromCodePoint(a) + String.fromCodePoint(b);
  const n = s.normalize('NFD');
  return n === String.fromCodePoint(b) + String.fromCodePoint(a);
