const REF9 = 0x094D;   // DEVANAGARI SIGN VIRAMA, ccc=9
const REF1 = 0x0334;   // COMBINING TILDE OVERLAY, ccc=1

const isStable = cp => { const s=String.fromCodePoint(cp); return s.normalize('NFD') === s; };

const found = [];
const markRe = /\p{M}/u;
for (let cp=0; cp<=0x10FFFF; cp++){
  if (cp>=0xD800 && cp<=0xDFFF) continue;
  const s = String.fromCodePoint(cp);
  if (!markRe.test(s)) continue;      // ccc>0 implies it's a mark (Mn/Mc/Me)
  if (!isStable(cp)) continue;        // skip chars with canonical decompositions
  // ccc == 9  <=>  not(ccc>9) and not(9>ccc>0) and ccc>1
