#!/usr/bin/env node
// gen-unicode-aux.mjs — generates /tmp/wf/unicode-aux.mjs
//
// Derives the auxiliary Unicode tables needed by IDNA2008 (RFC 5891/5892) validation
// using ONLY Node's own Unicode data, exposed through RegExp \p{...} property escapes
// and String.prototype.normalize. No npm packages, no network, no UCD text files.
//
// Node 18 ESM. Run:  node /tmp/wf/gen-unicode-aux.mjs
//
// ---------------------------------------------------------------------------
// What is genuinely DERIVED vs. what is CURATED
// ---------------------------------------------------------------------------
//  * bidiClassOf     : derived  (defaults-by-range + \p{gc}/\p{Script}/\p{scx} overrides,
//                                plus a small, explicitly listed exception table)
//  * isVirama        : derived  (ccc==9 recovered by probing NFD canonical ordering)
//  * isCombiningMark : derived  (\p{M})
//  * joiningTypeOf   : PARTLY derived. Arabic D/R is recovered exactly from the
//                      compatibility decompositions of the Arabic Presentation Forms
//                      blocks; everything else is curated best-effort (see JOIN_CURATED).
// ---------------------------------------------------------------------------

import { writeFileSync } from 'node:fs';

const OUT = '/tmp/wf/unicode-aux.mjs';
const MAXCP = 0x10ffff;
const isSurrogate = (cp) => cp >= 0xd800 && cp <= 0xdfff;
const chr = (cp) => String.fromCodePoint(cp);
const hex = (cp) => cp.toString(16).toUpperCase().padStart(4, '0');

// ===========================================================================
// 1. BIDI CLASS
// ===========================================================================

// --- 1a. The @missing default ranges from DerivedBidiClass.txt ------------
const AL_DEFAULT = [
  [0x0600, 0x07bf], [0x0860, 0x08ff], [0xfb50, 0xfdcf], [0xfdf0, 0xfdff],
  [0xfe70, 0xfeff], [0x10d00, 0x10d3f], [0x10ec0, 0x10eff], [0x10f30, 0x10f6f],
  [0x1ec70, 0x1ecbf], [0x1ed00, 0x1ed4f], [0x1ee00, 0x1eeff],
];
const R_DEFAULT = [
  [0x0590, 0x05ff], [0x07c0, 0x085f], [0xfb1d, 0xfb4f], [0x10800, 0x10cff],
  [0x10d40, 0x10ebf], [0x10f00, 0x10f2f], [0x10f70, 0x10fff], [0x1e800, 0x1ec6f],
  [0x1ecc0, 0x1ecff], [0x1ed50, 0x1edff], [0x1ef00, 0x1efff],
];
const ET_DEFAULT = [[0x20a0, 0x20cf]]; // currency symbols -> merged into NEUTRAL

const inRanges = (cp, rs) => {
  for (let i = 0; i < rs.length; i++) if (cp >= rs[i][0] && cp <= rs[i][1]) return true;
  return false;
};
function rangeDefault(cp) {
  if (inRanges(cp, AL_DEFAULT)) return 'AL';
  if (inRanges(cp, R_DEFAULT)) return 'R';
  if (inRanges(cp, ET_DEFAULT)) return 'NEUTRAL';
  return 'L';
}

// --- 1b. Script -> direction ----------------------------------------------
// NOTE: the four entries commented out below were in the candidate list handed to
// this generator but are WRONG, verified against Unicode's own Bidi_Class data:
//   Manichaean, Chorasmian, Old_Uyghur -> actually R (not AL); all three sit inside
//                                          R default blocks (10800..10CFF / 10F70..10FFF)
//   Cypro_Minoan                       -> actually L (not R); U+12F90.. is outside every
//                                          RTL default block
const AL_SCRIPTS = ['Arabic', 'Syriac', 'Thaana', 'Sogdian', 'Hanifi_Rohingya'];
const R_SCRIPTS = [
  'Hebrew', 'Nko', 'Samaritan', 'Mandaic', 'Adlam', 'Cypriot', 'Phoenician', 'Lydian',
  'Kharoshthi', 'Imperial_Aramaic', 'Avestan', 'Inscriptional_Parthian',
  'Inscriptional_Pahlavi', 'Psalter_Pahlavi', 'Old_Turkic', 'Old_Hungarian', 'Hatran',
  'Elymaic', 'Nabataean', 'Palmyrene', 'Mende_Kikakui', 'Old_North_Arabian',
  'Old_South_Arabian', 'Old_Sogdian', 'Yezidi', 'Meroitic_Cursive',
  'Meroitic_Hieroglyphs', 'Manichaean', 'Chorasmian', 'Old_Uyghur',
];
const cls = (names, prop) => new RegExp(`[${names.map((n) => `\\p{${prop}=${n}}`).join('')}]`, 'u');
const reScriptAL = cls(AL_SCRIPTS, 'Script');
const reScriptR = cls(R_SCRIPTS, 'Script');
const reScxAL = cls(AL_SCRIPTS, 'Script_Extensions');
const reScxR = cls(R_SCRIPTS, 'Script_Extensions');

const reUnassigned = /\p{Cn}/u;
const reNSM = /[\p{Mn}\p{Me}]/u;
const reLetter = /\p{L}/u;
const reNd = /\p{Nd}/u;
const reNumOther = /[\p{No}\p{Nl}]/u;
// Sc/Sk/Sm (currency, modifier and math symbols) are Bidi ON even inside LTR scripts;
// So (other symbols) instead follows its script's direction. Verified empirically.
const reSymNeutral = /[\p{Sc}\p{Sk}\p{Sm}]/u;
const rePSZ = /[\p{P}\p{S}\p{Z}\p{Cf}\p{Cc}]/u;
const reGenericCommon = /[\p{Script_Extensions=Common}\p{Script_Extensions=Inherited}]/u;
const reCommonScript = /[\p{Script=Common}\p{Script=Inherited}]/u;
const reBNDefault = /[\p{Noncharacter_Code_Point}\p{Default_Ignorable_Code_Point}]/u;

// --- 1c. Explicit exceptions ----------------------------------------------
// Unicode assigns these values individually; no property-based rule reproduces them.
// Every entry here was cross-checked against Unicode's published Bidi_Class.
const BIDI_EXCEPTIONS = [];
const bx = (a, b, v) => BIDI_EXCEPTIONS.push([a, b, v]);

// C0/C1 controls: BN, except the whitespace/paragraph separators which are WS/B/S.
bx(0x0000, 0x0008, 'BN'); bx(0x0009, 0x000d, 'NEUTRAL'); bx(0x000e, 0x001b, 'BN');
bx(0x001c, 0x001f, 'NEUTRAL'); bx(0x007f, 0x0084, 'BN'); bx(0x0085, 0x0085, 'NEUTRAL');
bx(0x0086, 0x009f, 'BN');

// ASCII digits / hyphen-minus (ES).
bx(0x0030, 0x0039, 'EN'); bx(0x002d, 0x002d, 'NEUTRAL');

// Arabic numerics.
bx(0x0600, 0x0605, 'AN'); bx(0x0660, 0x0669, 'AN'); bx(0x066b, 0x066c, 'AN');
bx(0x06dd, 0x06dd, 'AN'); bx(0x0890, 0x0891, 'AN'); bx(0x08e2, 0x08e2, 'AN');
bx(0x06f0, 0x06f9, 'EN');                       // extended Arabic-Indic digits are EN
bx(0x10d30, 0x10d39, 'AN');                     // Hanifi Rohingya digits
bx(0x10e60, 0x10e7e, 'AN');                     // Rumi numeral symbols

// Explicit bidi formatting characters.
bx(0x200e, 0x200e, 'L'); bx(0x200f, 0x200f, 'R'); bx(0x061c, 0x061c, 'AL');
bx(0x202a, 0x202e, 'NEUTRAL'); bx(0x2066, 0x2069, 'NEUTRAL'); bx(0xfff9, 0xfffb, 'NEUTRAL');
bx(0x180e, 0x180e, 'BN');

// Common-script digit-like No/Nd that are EN (super/subscripts, fullwidth, math, segmented).
for (const [a, b] of [[0x00b2, 0x00b3], [0x00b9, 0x00b9], [0x2070, 0x2070], [0x2074, 0x2079],
  [0x2080, 0x2089], [0x2488, 0x249b], [0xff10, 0xff19], [0x102e1, 0x102fb],
  [0x1d7ce, 0x1d7ff], [0x1f100, 0x1f10a], [0x1fbf0, 0x1fbf9]]) bx(a, b, 'EN');

// Common-script modifier letters that are ON rather than L.
for (const [a, b] of [[0x02b9, 0x02ba], [0x02c6, 0x02cf], [0x02ec, 0x02ec], [0x0374, 0x0374],
  [0x2cfd, 0x2cfd], [0x2e2f, 0x2e2f], [0xa67f, 0xa67f], [0xa717, 0xa71f],
  [0xa788, 0xa788]]) bx(a, b, 'NEUTRAL');

// Marks (Mn) whose Bidi_Class is L, not NSM — the "NSM == Mn|Me" shortcut is not exact.
const NSM_EXCEPTIONS = new Set([0x0cbf, 0x0cc6, 0x11a07, 0x11a08, 0x11c3f]);

// Symbols/punctuation inside RTL blocks whose class differs from the block default.
for (const [a, b] of [[0x0609, 0x060a], [0x060c, 0x060c], [0x060e, 0x060f], [0x066a, 0x066a],
  [0x06de, 0x06de], [0x06e9, 0x06e9], [0xfd3e, 0xfd3f], [0xfd40, 0xfd4f],
  [0x07f6, 0x07f9], [0x1091f, 0x1091f], [0x10b39, 0x10b3f]]) bx(a, b, 'NEUTRAL');
for (const [a, b] of [[0x0608, 0x0608], [0x060b, 0x060b], [0x06fd, 0x06fe],
  [0x0888, 0x0888]]) bx(a, b, 'AL');
for (const [a, b] of [[0x07fe, 0x07ff], [0x10877, 0x10878], [0x10ac8, 0x10ac8]]) bx(a, b, 'R');

const bidiExceptionMap = new Map();
for (const [a, b, v] of BIDI_EXCEPTIONS) for (let c = a; c <= b; c++) bidiExceptionMap.set(c, v);

// --- 1d. The derivation ----------------------------------------------------
function deriveBidi(cp) {
  const s = chr(cp);

  // Unassigned: fall back to the @missing range defaults.
  if (reUnassigned.test(s)) return reBNDefault.test(s) ? 'BN' : rangeDefault(cp);

  const ex = bidiExceptionMap.get(cp);
  if (ex !== undefined) return ex;

  if (reNSM.test(s) && !NSM_EXCEPTIONS.has(cp)) return 'NSM';

  const symbolIsNeutral = reSymNeutral.test(s);

  if (!reCommonScript.test(s)) {
    // A concrete script: letters, marks, digits and script punctuation take the
    // script's direction; currency/math/modifier symbols stay neutral.
    if (symbolIsNeutral) return 'NEUTRAL';
    if (reScriptAL.test(s)) return 'AL';
    if (reScriptR.test(s)) return 'R';
    return 'L';
  }

