  if(cp<r[0])hi=m-1;else if(cp>r[1])lo=m+1;else return r[2];}return 'UNASSIGNED';};
const hx=c=>c.toString(16).toUpperCase().padStart(4,'0');
const want={'L -> R':[], 'AL -> NEUTRAL':[], 'BN -> L':[], 'NEUTRAL -> AL':[], 'NEUTRAL -> R':[]};
const MERGE={ES:'NEUTRAL',CS:'NEUTRAL',ET:'NEUTRAL',ON:'NEUTRAL',WS:'NEUTRAL',B:'NEUTRAL',S:'NEUTRAL',
 LRE:'NEUTRAL',RLE:'NEUTRAL',LRO:'NEUTRAL',RLO:'NEUTRAL',PDF:'NEUTRAL',LRI:'NEUTRAL',RLI:'NEUTRAL',FSI:'NEUTRAL',PDI:'NEUTRAL'};
for(let cp=0;cp<=0x10FFFF;cp++){ if(cp>=0xD800&&cp<=0xDFFF)continue;
